        126.9896211 AS LONGITUDE,
        CAST(NULL AS VARCHAR2(100)) AS PHONE,
        q'~http://place.map.kakao.com/1336827498~' AS PLACE_URL,
        0 AS RATING,
        0 AS REVIEW_COUNT,
        CAST(NULL AS VARCHAR2(4000)) AS DESCRIPTION,
        CAST(NULL AS VARCHAR2(1000)) AS IMAGE_URL,
        CAST(NULL AS VARCHAR2(100)) AS IMAGE_SOURCE,
        CAST(NULL AS NUMBER) AS IMAGE_MATCH_SCORE,
        q'~NOT_FOUND~' AS IMAGE_STATUS,
        CAST(NULL AS VARCHAR2(30)) AS IMAGE_LICENSE_TYPE,
        CAST(NULL AS VARCHAR2(1000)) AS IMAGE_ATTRIBUTION,
        q'~N~' AS TAG_HISTORY,
        q'~Y~' AS TAG_MODERN,
        q'~N~' AS TAG_BUDGET,
        q'~N~' AS TAG_LUXURY,
        q'~N~' AS TAG_STABLE,
        q'~Y~' AS TAG_DOPAMINE,
        q'~Y~' AS TAG_RELAX,
        q'~N~' AS TAG_PACKED,
        q'~N~' AS THEME_PALACE_CULTURE_YN,
        q'~N~' AS THEME_NATURE_HANGANG_YN,
        q'~N~' AS THEME_DATE_YN,
        q'~N~' AS THEME_FOOD_TOUR_YN,
        q'~N~' AS THEME_CAFE_TOUR_YN,
        q'~N~' AS THEME_SHOPPING_HOTPLACE_YN,
        q'~N~' AS THEME_NIGHT_VIEW_YN,
        q'~N~' AS THEME_HOTEL_STAY_YN,
        q'~RECOMMEND~' AS SOURCE_TYPE,
        q'~Y~' AS RECOMMEND_YN,
        q'~APPROVED~' AS APPROVAL_STATUS,
        CAST(NULL AS NUMBER) AS CREATED_BY_MEMBER_ID,
        q'~N~' AS INDOOR_YN,
        q'~N~' AS RAIN_OK_YN,
        q'~N~' AS NIGHT_OK_YN,
        60 AS AVG_STAY_MINUTES,
        q'~MEDIUM~' AS PRICE_LEVEL,
        q'~Y~' AS IS_ACTIVE
FROM DUAL
) S
ON (
    P.NAME = S.NAME
    AND P.CATEGORY = S.CATEGORY
)
WHEN MATCHED THEN
    UPDATE SET
        P.API_PROVIDER = S.API_PROVIDER,
        P.API_PLACE_ID = S.API_PLACE_ID,
        P.API_CATEGORY = S.API_CATEGORY,
        P.REGION = S.REGION,
        P.ADDRESS = S.ADDRESS,
        P.ROAD_ADDRESS = S.ROAD_ADDRESS,
        P.LATITUDE = S.LATITUDE,
        P.LONGITUDE = S.LONGITUDE,
        P.RATING = S.RATING,
        P.REVIEW_COUNT = S.REVIEW_COUNT,
        P.TAG_HISTORY = S.TAG_HISTORY,
        P.TAG_MODERN = S.TAG_MODERN,
        P.TAG_BUDGET = S.TAG_BUDGET,
        P.TAG_LUXURY = S.TAG_LUXURY,
        P.TAG_STABLE = S.TAG_STABLE,
        P.TAG_DOPAMINE = S.TAG_DOPAMINE,
        P.TAG_RELAX = S.TAG_RELAX,
        P.TAG_PACKED = S.TAG_PACKED,
        P.THEME_PALACE_CULTURE_YN = S.THEME_PALACE_CULTURE_YN,
        P.THEME_NATURE_HANGANG_YN = S.THEME_NATURE_HANGANG_YN,
        P.THEME_DATE_YN = S.THEME_DATE_YN,
        P.THEME_FOOD_TOUR_YN = S.THEME_FOOD_TOUR_YN,
        P.THEME_CAFE_TOUR_YN = S.THEME_CAFE_TOUR_YN,
        P.THEME_SHOPPING_HOTPLACE_YN = S.THEME_SHOPPING_HOTPLACE_YN,
        P.THEME_NIGHT_VIEW_YN = S.THEME_NIGHT_VIEW_YN,
        P.THEME_HOTEL_STAY_YN = S.THEME_HOTEL_STAY_YN,
        P.SOURCE_TYPE = S.SOURCE_TYPE,
        P.RECOMMEND_YN = S.RECOMMEND_YN,
        P.APPROVAL_STATUS = S.APPROVAL_STATUS,
        P.CREATED_BY_MEMBER_ID = S.CREATED_BY_MEMBER_ID,
        P.INDOOR_YN = S.INDOOR_YN,
        P.RAIN_OK_YN = S.RAIN_OK_YN,
        P.NIGHT_OK_YN = S.NIGHT_OK_YN,
        P.AVG_STAY_MINUTES = S.AVG_STAY_MINUTES,
        P.PRICE_LEVEL = S.PRICE_LEVEL,
        P.IS_ACTIVE = S.IS_ACTIVE,
        P.CONTENT_ID = COALESCE(S.CONTENT_ID, P.CONTENT_ID),
        P.PHONE = COALESCE(S.PHONE, P.PHONE),
        P.PLACE_URL = COALESCE(S.PLACE_URL, P.PLACE_URL),
        P.DESCRIPTION = NVL(TO_CLOB(S.DESCRIPTION), P.DESCRIPTION),
        P.IMAGE_URL = COALESCE(S.IMAGE_URL, P.IMAGE_URL),
        P.IMAGE_SOURCE = COALESCE(S.IMAGE_SOURCE, P.IMAGE_SOURCE),
        P.IMAGE_MATCH_SCORE = CASE
            WHEN S.IMAGE_MATCH_SCORE IS NULL THEN P.IMAGE_MATCH_SCORE
            ELSE LEAST(100, GREATEST(0, S.IMAGE_MATCH_SCORE))
        END,
        P.IMAGE_STATUS = COALESCE(S.IMAGE_STATUS, P.IMAGE_STATUS),
        P.IMAGE_LICENSE_TYPE = COALESCE(S.IMAGE_LICENSE_TYPE, P.IMAGE_LICENSE_TYPE),
        P.IMAGE_ATTRIBUTION = COALESCE(S.IMAGE_ATTRIBUTION, P.IMAGE_ATTRIBUTION),
        P.UPDATED_AT = SYSDATE
WHEN NOT MATCHED THEN
    INSERT (
        API_PROVIDER,
        API_PLACE_ID,
        CONTENT_ID,
        NAME,
        CATEGORY,
        API_CATEGORY,
        REGION,
        ADDRESS,
        ROAD_ADDRESS,
        LATITUDE,
        LONGITUDE,
        PHONE,
        PLACE_URL,
        RATING,
        REVIEW_COUNT,
        DESCRIPTION,
        IMAGE_URL,
        IMAGE_SOURCE,
        IMAGE_MATCH_SCORE,
        IMAGE_STATUS,
        IMAGE_LICENSE_TYPE,
        IMAGE_ATTRIBUTION,
        TAG_HISTORY,
        TAG_MODERN,
        TAG_BUDGET,
        TAG_LUXURY,
        TAG_STABLE,
        TAG_DOPAMINE,
        TAG_RELAX,
        TAG_PACKED,
        THEME_PALACE_CULTURE_YN,
        THEME_NATURE_HANGANG_YN,
        THEME_DATE_YN,
        THEME_FOOD_TOUR_YN,
        THEME_CAFE_TOUR_YN,
        THEME_SHOPPING_HOTPLACE_YN,
        THEME_NIGHT_VIEW_YN,
        THEME_HOTEL_STAY_YN,
        SOURCE_TYPE,
        RECOMMEND_YN,
        APPROVAL_STATUS,
        CREATED_BY_MEMBER_ID,
        INDOOR_YN,
        RAIN_OK_YN,
        NIGHT_OK_YN,
        AVG_STAY_MINUTES,
        PRICE_LEVEL,
        IS_ACTIVE,
        CREATED_AT,
        UPDATED_AT
    )
    VALUES (
        S.API_PROVIDER,
        S.API_PLACE_ID,
        S.CONTENT_ID,
        S.NAME,
        S.CATEGORY,
        S.API_CATEGORY,
        S.REGION,
        S.ADDRESS,
        S.ROAD_ADDRESS,
        S.LATITUDE,
        S.LONGITUDE,
        S.PHONE,
        S.PLACE_URL,
        S.RATING,
        S.REVIEW_COUNT,
        S.DESCRIPTION,
        S.IMAGE_URL,
        S.IMAGE_SOURCE,
        CASE
            WHEN S.IMAGE_MATCH_SCORE IS NULL THEN NULL
            ELSE LEAST(100, GREATEST(0, S.IMAGE_MATCH_SCORE))
        END,
        S.IMAGE_STATUS,
        S.IMAGE_LICENSE_TYPE,
        S.IMAGE_ATTRIBUTION,
        S.TAG_HISTORY,
        S.TAG_MODERN,
        S.TAG_BUDGET,
        S.TAG_LUXURY,
        S.TAG_STABLE,
        S.TAG_DOPAMINE,
        S.TAG_RELAX,
        S.TAG_PACKED,
        S.THEME_PALACE_CULTURE_YN,
        S.THEME_NATURE_HANGANG_YN,
        S.THEME_DATE_YN,
        S.THEME_FOOD_TOUR_YN,
        S.THEME_CAFE_TOUR_YN,
        S.THEME_SHOPPING_HOTPLACE_YN,
        S.THEME_NIGHT_VIEW_YN,
        S.THEME_HOTEL_STAY_YN,
        S.SOURCE_TYPE,
        S.RECOMMEND_YN,
        S.APPROVAL_STATUS,
        S.CREATED_BY_MEMBER_ID,
        S.INDOOR_YN,
        S.RAIN_OK_YN,
        S.NIGHT_OK_YN,
        S.AVG_STAY_MINUTES,
        S.PRICE_LEVEL,
        S.IS_ACTIVE,
        SYSDATE,
        SYSDATE
    );

COMMIT;
